  'Pat pat. More pages please.',
  'I purr. Bookworms can purr. Look it up.',
  'Mind the glasses.',
  'Again!',
}

L.DREAM = {
  'dreaming of {title}…',
  'dreaming of page {page}…',
  'dreaming of a library with no closing time…',
  'dreaming of the next chapter…',
}
L.DREAM_HUNGRY = { 'dreaming of snacks…', 'dreaming of a very long book…' }
L.DREAM_EGG = { 'an egg, resting' }

-- the lines of a kind of creature (pet.lua SPECIES): the bookworm's are these, the others' are a
-- module each (lines_<key>.lua), loaded only when that one is awake; anything they lack is the
-- bookworm's
local voices = {}
function L.voice(key)
  if not key or key == 'worm' then return L end
  if not voices[key] then voices[key] = setmetatable(require('lines_' .. key), { __index = L }) end
  return voices[key]
end

local function short(s, n)
  s = tostring(s or '')
  if utf8.len(s) and utf8.len(s) > n then
    local cut = utf8.offset(s, n) or (n + 1)
    return s:sub(1, cut - 1) .. '…'
  end
  return s
end
L.short = short

-- only the lines whose fields are all known (a book has no page number before it is paginated)
function L.known(list, f)
  local out = {}
  for _, s in ipairs(list) do
    local ok = true
    for k in s:gmatch('{(%a+)}') do if f[k] == nil or f[k] == '' then ok = false end end
    if ok then out[#out + 1] = s end
  end
  return #out > 0 and out or list
end

-- one line of list, by seed, with its fields filled in
function L.pick(list, seed, f)
  if not list or #list == 0 then return '' end
  local s = list[(seed % #list) + 1]
  f = f or {}
  return (s:gsub('{(%a+)}', function(k)
    local v = f[k]
    if v == nil or v == '' then
      if k == 'title' then return 'this book' end
      if k == 'pct' then return 'some' end
      return '…'
    end
    return tostring(v)
  end))
end

return L
end

